// Generated by scripts/build-builder-templates.mjs from the guide pages. Do not edit by hand.

export const TEMPLATES: Record<string, string> = {
  "actor": "namespace HelloBox\n{\n    public static class HelloActors\n    {\n        public const string SPRITE = \"hello_sprite\";\n\n        public static void Initialize()\n        {\n            if (AssetManager.actor_library.has(SPRITE)) return;\n\n            // clone() copies every field, gives the copy the new id, and registers it.\n            // Do NOT call add() afterwards: that registers it a second time and the\n            // library logs \"duplicate asset - overwriting...\".\n            ActorAsset sprite = AssetManager.actor_library.clone(SPRITE, \"human\");\n\n            sprite.name_locale = \"Sprite\";\n            sprite.civ = true;                       // founds cities, joins kingdoms, goes to war\n            sprite.can_have_subspecies = true;\n            sprite.actor_size = ActorSize.S13_Human;\n            sprite.color_hex = \"#7FE7C4\";\n            sprite.icon = \"iconHelloSprite\";\n\n            // visible immediately: no need to discover them first\n            sprite.needs_to_be_explored = false;\n\n            // Taxonomy: what the knowledge window shows.\n            sprite.name_taxonomic_genus = \"spiritus\";\n            sprite.name_taxonomic_species = \"minor\";\n\n            // Stats. clone() already ran add(), so base_stats exists here.\n            sprite.base_stats[\"health\"] = 80;\n            sprite.base_stats[\"damage\"] = 12;\n            sprite.base_stats[\"speed\"] = 32f;\n\n            // see the warning below: the shadow is not loaded for you\n            sprite.texture_asset.loadShadow();\n        }\n    }\n}",
  "building": "namespace HelloBox\n{\n    public static class HelloBuildings\n    {\n        public const string SHRINE = \"hello_shrine\";\n\n        public static void Initialize()\n        {\n            if (AssetManager.buildings.has(SHRINE)) return;\n\n            BuildingAsset shrine = AssetManager.buildings.clone(SHRINE, \"temple_human\");\n\n            shrine.sprite_path = \"buildings/hello_shrine\";   // a folder, used exactly as written\n\n            // The game preloads every building's frames during its own startup, before your\n            // mod existed. Load this one now, or placing it throws \"Index was out of range\".\n            shrine.loadBuildingSprites();\n\n            // Same story for the atlas that recolours it in the owner's colour: the library\n            // links it in checkAtlasLink() at startup. Without it every frame throws.\n            shrine.atlas_asset = AssetManager.dynamic_sprites_library.get(shrine.atlas_id);\n            shrine.building_type = BuildingType.Building_Civ;\n            shrine.city_building = true;\n            shrine.has_kingdom_color = true;\n            shrine.max_houses = 0;                     // not housing, nobody lives here\n            shrine.housing_slots = 0;\n            shrine.draw_light_area = true;\n            shrine.draw_light_size = 0.6f;\n        }\n    }\n}",
  "disaster": "namespace HelloBox\n{\n    public static class HelloDisasters\n    {\n        public const string EMBER_STORM = \"hello_ember_storm\";\n        public const string EMBER_STORM_LOG = \"disaster_hello_ember_storm\";\n\n        public static void Initialize()\n        {\n            if (AssetManager.disasters.has(EMBER_STORM)) return;\n\n            // The line in the world log. world_log below is the id of this asset, not a text key.\n            if (!AssetManager.world_log_library.has(EMBER_STORM_LOG))\n            {\n                WorldLogAsset log = AssetManager.world_log_library.clone(EMBER_STORM_LOG, \"$basic_disaster$\");\n                log.locale_id = \"worldlog_disaster_hello_ember_storm\";\n                log.path_icon = \"ui/Icons/iconHelloDisaster\";\n            }\n\n            DisasterAsset emberStorm = new DisasterAsset\n            {\n                id = EMBER_STORM,\n                rate = 4,                      // weight: how often it is picked vs other disasters\n                chance = 0.5f,                 // and then a coin flip on top\n                min_world_population = 100,    // don't ruin an empty world\n                min_world_cities = 1,\n                world_log = EMBER_STORM_LOG,\n                type = DisasterType.Nature\n            };\n\n            emberStorm.action = (DisasterAsset pAsset) =>\n            {\n                WorldTile first = null;\n\n                // 40 embers on random tiles. tiles_list is every tile in the world.\n                for (int i = 0; i < 40; i++)\n                {\n                    WorldTile tile = World.world.tiles_list[Randy.randomInt(0, World.world.tiles_list.Length)];\n                    if (tile == null) continue;\n                    if (first == null) first = tile;\n                    World.world.drop_manager.spawn(tile, \"hello_ember\", 15f, -1f, -1L);\n                }\n\n                // one line in the log, pointing at where it started\n                if (first != null) WorldLog.logDisaster(pAsset, first);\n            };\n\n            AssetManager.disasters.add(emberStorm);\n        }\n    }\n}",
  "combat": "using UnityEngine;\n\nnamespace HelloBox\n{\n    public static class HelloCombat\n    {\n        public const string TOSS = \"hello_ember_toss\";\n\n        public static void Initialize()\n        {\n            if (AssetManager.combat_action_library.has(TOSS)) return;\n\n            CombatActionAsset toss = new CombatActionAsset\n            {\n                id = TOSS,\n                cost_stamina = 10,\n                chance = 0.3f,        // rolled each time the unit could use it, plus its combat skill\n                cooldown = 4f,\n                pools = new CombatActionPool[] { CombatActionPool.BEFORE_ATTACK_MELEE },\n\n                // same range as the vanilla torch throw: not point blank, not across the map\n                can_do_action = (Actor pSelf, BaseSimObject pTarget) =>\n                {\n                    float dist = Toolbox.SquaredDistVec2Float(pSelf.current_position, pTarget.current_position);\n                    return dist > 36f && dist < 2500f;\n                },\n\n                action_actor_target_position = (Actor pSelf, Vector2 pTarget, WorldTile pTile) =>\n                {\n                    if (pSelf == null || !pSelf.isAlive() || pTile == null) return false;\n\n                    Vector3 launch = pSelf.current_position;\n                    launch.y += 0.5f;\n                    // a shooter means a kingdom, so no pForcedKingdom here\n                    World.world.projectiles.spawn(pSelf, null, HelloProjectiles.EMBER_BOLT, launch, pTile.posV3);\n                    MusicBox.playSound(\"event:/SFX/WEAPONS/WeaponFireballStart\", pTile);\n                    return true;\n                }\n            };\n\n            AssetManager.combat_action_library.add(toss);\n\n            // Combat actions come from traits. The trait only stores ids, and the game turned\n            // ids into objects at startup: link it yourself or the trait never uses it.\n            ActorTrait swift = AssetManager.traits.get(HelloTraits.SWIFT);\n            if (swift == null) return;\n            swift.addCombatAction(TOSS);\n            swift.linkCombatActions();\n        }\n    }\n}",
  "ai_job": "using ai.behaviours;   // BehaviourTaskActor, BehaviourActionActor, BehResult, the vanilla behaviours\n\nnamespace HelloBox\n{\n    public class BehHelloDrive : BehaviourActionActor\n    {\n        public override BehResult execute(Actor pActor)\n        {\n            if (pActor == null || !pActor.isAlive()) return BehResult.Stop;\n\n            WorldTile target = HelloAI.PickTile(pActor);\n            if (target == null) return BehResult.Stop;\n\n            pActor.beh_tile_target = target;\n            return BehResult.Continue;\n        }\n    }\n\n    public static class HelloAI\n    {\n        public const string JOB = \"hellobox_job\";\n        public const string TASK = \"hellobox_drive\";\n\n        public static void Initialize()\n        {\n            BehaviourTaskActor drive = new BehaviourTaskActor\n            {\n                id = TASK,\n                ignore_fight_check = true,        // don't let the combat system hijack the task\n                locale_key = \"task_unit_\" + TASK\n            };\n\n            AssetManager.tasks_actor.add(drive);  // add first\n            drive.setIcon(\"ui/Icons/iconHelloDrive\");    // then decorate\n            drive.addBeh(new BehHelloDrive());    // my decision\n            drive.addBeh(new BehGoToTileTarget()); // the game's own pathing does the walking\n\n            ActorJob job = new ActorJob { id = JOB };\n            job.addTask(TASK);\n            AssetManager.job_actor.add(job);\n        }\n\n        /** Where the creature should walk next. One random neighbour it can actually reach. */\n        public static WorldTile PickTile(Actor pActor)\n        {\n            WorldTile from = pActor.current_tile;\n            if (from == null) return null;\n\n            // the game's own helper: a random neighbour that is not across water\n            return from.getTileAroundThisOnSameIsland(from);\n        }\n    }\n}",
  "decision": "namespace HelloBox\n{\n    public static class HelloDecisions\n    {\n        public const string WANDER = \"hello_decide_wander\";\n\n        public static void Initialize()\n        {\n            if (AssetManager.decisions_library.has(WANDER)) return;\n\n            DecisionAsset wander = new DecisionAsset\n            {\n                id = WANDER,\n                task_id = HelloAI.TASK,                  // the decision says when, the task says how\n                priority = NeuroLayer.Layer_1_Low,\n                path_icon = \"ui/Icons/iconHelloDrive\",\n                cooldown = 20,                           // seconds before this unit may pick it again\n                weight = 1f,\n                unique = true,                           // only the actors you give it to, below\n                action_check_launch = (Actor pActor) => pActor != null && pActor.isAlive() && !pActor.isFighting()\n            };\n\n            AssetManager.decisions_library.add(wander);\n\n            // linkAssets() fills these three for every decision, at startup, before your mod.\n            // decision_index is where each unit keeps this decision's cooldown: left at 0, yours\n            // would share it with the first vanilla decision.\n            wander.decision_index = AssetManager.decisions_library.list.IndexOf(wander);\n            wander.priority_int_cached = (int)wander.priority;\n            wander.has_weight_custom = wander.weight_calculate_custom != null;\n\n            // who gets it: every wisp, through its actor asset\n            ActorAsset wisp = AssetManager.actor_library.get(\"hello_wisp\");\n            if (wisp != null) wisp.addDecision(WANDER);\n        }\n    }\n}",
  "city_job": "using ai.behaviours;   // CityBehCheckCitizenTasks\nusing HarmonyLib;\n\nnamespace HelloBox\n{\n    public static class HelloCityJobs\n    {\n        public const string KEEPER = \"hello_ember_keeper\";\n\n        public static void Initialize()\n        {\n            if (AssetManager.citizen_job_library.has(KEEPER)) return;\n\n            // What the citizen does once hired: an actor job with the same id\n            ActorJob work = new ActorJob { id = KEEPER };\n            work.addTask(HelloAI.TASK);\n            work.addTask(\"end_job\");\n            AssetManager.job_actor.add(work);\n\n            CitizenJobAsset keeper = new CitizenJobAsset\n            {\n                id = KEEPER,\n                path_icon = \"ui/Icons/iconHelloDrive\"\n            };\n            AssetManager.citizen_job_library.add(keeper);\n\n            // post_init() and linkAssets() did these two at startup\n            keeper.unit_job_default = KEEPER;\n            AssetManager.citizen_job_library.list_priority_normal.Add(keeper);\n        }\n\n        // A city hands out job slots in one behaviour, from a fixed list of vanilla jobs.\n        // Nothing ever opens a slot for yours unless you add it after that list.\n        [HarmonyPatch(typeof(CityBehCheckCitizenTasks), nameof(CityBehCheckCitizenTasks.execute))]\n        public static class Patch_CitizenTasks\n        {\n            public static void Postfix(City pCity)\n            {\n                if (pCity == null || pCity.status.population_adults < 10) return;\n\n                CitizenJobAsset keeper = AssetManager.citizen_job_library.get(KEEPER);\n                if (keeper == null) return;\n\n                // one keeper per city, recomputed every time the city recounts its jobs\n                if (pCity.jobs.countCurrentJobs(keeper) == 0) pCity.jobs.addToJob(keeper, 1);\n            }\n        }\n    }\n}",
  "plot": "namespace HelloBox\n{\n    public static class HelloPlots\n    {\n        public const string FESTIVAL = \"hello_ember_festival\";\n\n        public static void Initialize()\n        {\n            if (AssetManager.plots_library.has(FESTIVAL)) return;\n\n            PlotAsset festival = new PlotAsset\n            {\n                id = FESTIVAL,\n                path_icon = \"ui/Icons/iconHelloDrop\",\n                group_id = \"culture\",\n                is_basic_plot = true,            // any leader may try it, no religion needed\n                pot_rate = 2,                    // weight against the other plots\n                min_level = 1,\n                money_cost = 10,\n                progress_needed = 40f,\n                can_be_done_by_king = true,\n                can_be_done_by_leader = true,\n                needs_to_be_explored = false,\n\n                // called with no null check: a plot without it crashes the first time anyone looks at it\n                check_is_possible = (Actor pActor) => pActor != null && pActor.isAlive() && pActor.hasCity() && !pActor.city.isInDanger(),\n                check_should_continue = (Actor pActor) => pActor != null && pActor.isAlive() && pActor.hasCity(),\n\n                // runs once, when the progress bar is full\n                action = (Actor pActor) =>\n                {\n                    if (pActor == null || !pActor.isAlive()) return false;\n                    City city = pActor.city;\n                    if (city == null) return false;\n\n                    foreach (Actor unit in city.units)\n                    {\n                        if (unit != null && unit.isAlive()) unit.changeHappiness(HelloPolitics.WARM);\n                    }\n\n                    WorldTile tile = pActor.current_tile;\n                    if (tile != null) World.world.drop_manager.spawn(tile, \"hello_ember\", 15f, -1f, -1L);\n                    return true;\n                }\n            };\n\n            AssetManager.plots_library.add(festival);\n\n            // linkAssets() sorted the basic plots into their own list at startup,\n            // and that list is the only one leaders pick from\n            AssetManager.plots_library.basic_plots.Add(festival);\n        }\n    }\n}",
  "window": "using UnityEngine;\nusing UnityEngine.UI;\nusing UnityEngine.EventSystems;\n\nnamespace HelloBox\n{\n    public class HelloWindow : MonoBehaviour, IDragHandler\n    {\n        private static HelloWindow instance;\n        private RectTransform rect;\n\n        public static void Toggle()\n        {\n            if (instance == null) Build();\n            else instance.gameObject.SetActive(!instance.gameObject.activeSelf);\n        }\n\n        private static void Build()\n        {\n            Transform parent = CanvasMain.instance.canvas_ui.transform;\n\n            GameObject root = new GameObject(\"HelloBox_Window\");\n            root.transform.SetParent(parent, false);\n\n            Canvas layer = root.AddComponent<Canvas>();\n            layer.overrideSorting = true;\n            layer.sortingOrder = 30240;\n            root.AddComponent<GraphicRaycaster>();   // clicks land on the window, not the map\n\n            instance = root.AddComponent<HelloWindow>();\n            instance.rect = root.GetComponent<RectTransform>();\n            instance.rect.anchorMin = new Vector2(0f, 1f);\n            instance.rect.anchorMax = new Vector2(0f, 1f);\n            instance.rect.pivot = new Vector2(0f, 1f);\n            instance.rect.anchoredPosition = new Vector2(100f, -80f);\n            instance.rect.sizeDelta = new Vector2(240f, 300f);\n\n            Image background = root.AddComponent<Image>();\n            background.color = new Color(0.16f, 0.18f, 0.15f, 0.98f);\n\n            // Resize grip at the bottom-right corner\n            GameObject handle = new GameObject(\"ResizeHandle\");\n            handle.transform.SetParent(root.transform, false);\n\n            RectTransform handleRect = handle.AddComponent<RectTransform>();\n            handleRect.anchorMin = new Vector2(1f, 0f);\n            handleRect.anchorMax = new Vector2(1f, 0f);\n            handleRect.pivot = new Vector2(1f, 0f);\n            handleRect.anchoredPosition = Vector2.zero;\n            handleRect.sizeDelta = new Vector2(20f, 20f);\n\n            Image handleImg = handle.AddComponent<Image>();\n            handleImg.color = new Color(0.5f, 0.5f, 0.5f, 0.6f);\n\n            handle.AddComponent<HelloWindowResize>().target = instance.rect;\n\n            // hover the panel for live numbers: see Tooltips below\n            root.AddComponent<HelloTooltipTarget>();\n        }\n\n        // Drag anywhere on the window background to move it around\n        public void OnDrag(PointerEventData eventData)\n        {\n            if (rect != null)\n            {\n                rect.anchoredPosition += eventData.delta;\n            }\n        }\n    }\n\n    public class HelloWindowResize : MonoBehaviour, IDragHandler\n    {\n        public RectTransform target;\n\n        // Drag the bottom-right corner to resize the window\n        public void OnDrag(PointerEventData eventData)\n        {\n            if (target != null)\n            {\n                float newWidth = Mathf.Max(160f, target.sizeDelta.x + eventData.delta.x);\n                float newHeight = Mathf.Max(160f, target.sizeDelta.y - eventData.delta.y);\n                target.sizeDelta = new Vector2(newWidth, newHeight);\n            }\n        }\n    }\n}",
  "biome": "using System.Collections.Generic;\nusing UnityEngine;\n\nnamespace HelloBox\n{\n    public static class HelloBiomes\n    {\n        public const string BIOME = \"biome_hello_ember\";\n        public const string LOW = \"hello_ember_low\";\n        public const string HIGH = \"hello_ember_high\";\n        public const string SEEDS = \"seeds_hello_ember\";\n\n        public static void Initialize()\n        {\n            if (AssetManager.biome_library.has(BIOME)) return;\n\n            // 1. The ground. Clone the grass pair and point both at your biome.\n            TopTileType low = Tile(LOW, \"grass_low\", \"#B5582A\");\n            TopTileType high = Tile(HIGH, \"grass_high\", \"#8E4020\");\n\n            // 2. The biome.\n            BiomeAsset biome = new BiomeAsset\n            {\n                id = BIOME,\n                tile_low = LOW,\n                tile_high = HIGH,\n                localized_key = BIOME,              // its text key, in snake_case\n                spread_biome = true,                // grows into the grass next to it\n                spread_by_drops_water = true,\n                generator_pot_amount = 3,           // how often new worlds roll it. Grass uses 8\n                grow_type_selector_minerals = TileActionLibrary.getGrowTypeRandomMineral,\n                grow_type_selector_trees = TileActionLibrary.getGrowTypeRandomTrees,\n                grow_type_selector_plants = TileActionLibrary.getGrowTypeRandomPlants,\n                grow_type_selector_bushes = TileActionLibrary.getGrowTypeRandomBushes,\n                subspecies_name_suffix = new string[] { \"cinereus\", \"ardens\" }\n            };\n            AssetManager.biome_library.add(biome);\n\n            // what grows and what walks in. The number is the weight\n            biome.addTree(\"savanna_tree_1\", 3);\n            biome.addPlant(\"savanna_plant\");\n            biome.addBush(\"fruit_bush\");\n            biome.addMineral(\"mineral_stone\", 4);\n            biome.addUnit(\"hyena\");\n            biome.addUnit(\"buffalo\", 2);\n            biome.addSapientUnit(\"human\");\n\n            // born here, gets this. biome.addActorTrait() does the same, but it is internal:\n            // fine inside NML, a compile error in your own .dll. The list works everywhere\n            biome.spawn_trait_actor = new List<string> { \"fire_proof\" };\n\n            // linkAssets() built the world generator's pool at startup, before your mod existed.\n            for (int i = 0; i < biome.generator_pot_amount; i++)\n            {\n                BiomeLibrary.pool_biomes.Add(biome);\n            }\n\n            // now the tiles can link back to the biome that exists\n            low.biome_asset = biome;\n            high.biome_asset = biome;\n\n            // 3. The seeds. Clone the grass seeds and aim them at your two tiles.\n            DropAsset seeds = AssetManager.drops.clone(SEEDS, \"seeds_grass\");\n            seeds.drop_type_low = LOW;\n            seeds.drop_type_high = HIGH;\n            // DropsLibrary.linkAssets() turns those ids into tiles at startup. Do it yourself.\n            seeds.cached_drop_type_low = low;\n            seeds.cached_drop_type_high = high;\n\n            // 4. The power that throws them.\n            GodPower power = AssetManager.powers.clone(SEEDS, \"$template_seeds$\");\n            power.drop_id = SEEDS;\n            power.name = SEEDS;                     // also its text key\n            power.path_icon = \"ui/Icons/iconHelloSeeds\";\n        }\n\n        private static TopTileType Tile(string pId, string pFrom, string pColor)\n        {\n            TopTileType tile = AssetManager.top_tiles.clone(pId, pFrom);\n            tile.setBiome(BIOME);\n            tile.color_hex = pColor;\n\n            // [NonSerialized] fields: clone() skips them and linkAssets() already ran.\n            tile.color = Toolbox.makeColor(tile.color_hex);\n            tile.has_biome_tags = tile.biome_tags != null && tile.biome_tags.Count > 0;\n\n            // Inherit source tile sprites so rendering never encounters a null TileSprites\n            TopTileType source = AssetManager.top_tiles.get(pFrom);\n            if (source != null) tile.sprites = source.sprites;\n\n            // your art in GameResources/tiles/<id>/, loaded at startup in the vanilla case\n            Sprite[] variations = SpriteTextureLoader.getSpriteList(\"tiles/\" + tile.id);\n            if (variations != null && variations.Length > 0)\n            {\n                tile.sprites = new TileSprites();\n                foreach (Sprite variation in variations)\n                {\n                    tile.sprites.addVariation(variation, tile.id);\n                }\n            }\n            return tile;\n        }\n    }\n}",
  "names": "namespace HelloBox\n{\n    public static class HelloNames\n    {\n        public const string GENERATOR = \"hello_sprite_name\";\n        public const string SET = \"hello_sprite_set\";\n\n        public static void Initialize()\n        {\n            if (AssetManager.name_generator.has(GENERATOR)) return;\n\n            NameGeneratorAsset generator = new NameGeneratorAsset\n            {\n                id = GENERATOR,\n                // post_init() fills these two for part-group generators, and it already ran.\n                // Female names add a vowel from this list, so leaving it null crashes.\n                vowels = new string[] { \"a\", \"e\", \"i\", \"o\" },\n                consonants = NameGeneratorAsset.consonants_sounds\n            };\n\n            // one piece from each group, in order. An empty entry means \"sometimes nothing\"\n            generator.addPartGroup(\"ash,cin,em,sol,vol,ky\");\n            generator.addPartGroup(\"a,e,i,o,,\");\n            generator.addPartGroup(\"ra,dox,ber,rin,th,x\");\n            generator.addTemplate(\"Part_group\");   // capital P = first letter upper case\n\n            AssetManager.name_generator.add(generator);\n\n            // the same generator for everything these creatures ever name\n            AssetManager.name_sets.add(new NameSetAsset\n            {\n                id = SET,\n                unit = GENERATOR,\n                city = GENERATOR,\n                kingdom = GENERATOR,\n                clan = GENERATOR,\n                family = GENERATOR,\n                culture = GENERATOR,\n                language = GENERATOR,\n                religion = GENERATOR\n            });\n        }\n    }\n}",
  "book": "namespace HelloBox\n{\n    public static class HelloBooks\n    {\n        public const string ALMANAC = \"hello_ember_almanac\";\n        public const string TITLES = \"hello_book_titles\";\n\n        public static void Initialize()\n        {\n            Titles();\n\n            if (AssetManager.book_types.has(ALMANAC)) return;\n\n            BookTypeAsset almanac = new BookTypeAsset\n            {\n                id = ALMANAC,\n                name_template = TITLES,              // our own titles, below\n                color_text = \"#D14219\",\n                writing_rate = 2,\n                path_icons = \"hello_almanac/\",       // GameResources/books/book_icons/hello_almanac/\n                requirement_check = (Actor pActor, BookTypeAsset pAsset) => pActor.hasTrait(HelloTraits.SWIFT),\n                read_action = (Actor pActor, BookTypeAsset pAsset) =>\n                {\n                    // runs once per read, on the reader\n                    StatusAsset curse = AssetManager.status.get(HelloStatus.CURSED);\n                    if (curse != null) World.world.statuses.newStatus(pActor, curse, 0f);\n                }\n            };\n\n            AssetManager.book_types.add(almanac);\n\n            // what a reader gets out of it\n            almanac.base_stats[\"experience\"] = 5f;\n            almanac.base_stats[\"happiness\"] = 5f;\n            almanac.base_stats[\"intelligence\"] = 1f;   // this one is permanent, see below\n        }\n\n        /** A title generator in the dictionary style, built on the game's own book template. */\n        private static void Titles()\n        {\n            if (AssetManager.name_generator.has(TITLES)) return;\n\n            // $base_book_template$ already knows \"of\", \"and\", \"about\" and all the $name$ slots\n            NameGeneratorAsset titles = AssetManager.name_generator.clone(TITLES, \"$base_book_template$\");\n            titles.replacer += NameGeneratorReplacers.replaceOwnName;   // fills $unit$ with the writer\n            titles.replacer += NameGeneratorReplacers.replaceOwnCity;   // fills $city$\n\n            titles.addDictPart(\"almanac\", \"Almanac,Handbook,Notes,Scribbles,Field Guide\");\n            titles.addDictPart(\"fire\", \"Fire,Embers,Ash,Sparks,Smoke\");\n            titles.addTemplate(\"almanac,of,fire\");\n            titles.addTemplate(\"almanac,of,$unit$\");\n            titles.addTemplate(\"fire,and,$city$\");\n        }\n    }\n}",
  "war": "namespace HelloBox\n{\n    public static class HelloWars\n    {\n        public const string FEUD = \"hello_ember_feud\";\n        public const string NAMES = \"hello_war_feud\";\n\n        public static void Initialize()\n        {\n            Names();\n\n            if (AssetManager.war_types_library.has(FEUD)) return;\n\n            AssetManager.war_types_library.add(new WarTypeAsset\n            {\n                id = FEUD,\n                name_template = NAMES,                      // the generator for war names, below\n                localized_type = \"war_type_hello_ember_feud\",\n                localized_war_name = \"war_name_hello_ember_feud\",\n                path_icon = \"wars/war_hello_ember_feud\",    // GameResources/wars/war_hello_ember_feud.png\n                kingdom_for_name_attacker = true,           // $kingdom$ in the name = the attacker\n                alliance_join = true,                       // both sides' allies join\n                can_end_with_plot = true                    // a king can plot to end it\n            });\n        }\n\n        /** War names in the dictionary style: whole words picked from lists. */\n        private static void Names()\n        {\n            if (AssetManager.name_generator.has(NAMES)) return;\n\n            NameGeneratorAsset names = new NameGeneratorAsset\n            {\n                id = NAMES,\n                use_dictionary = true,\n                replacer_kingdom = NameGeneratorReplacers.replaceKingdom   // fills $kingdom$\n            };\n            names.addDictPart(\"kingdom_name\", \"$kingdom$\");\n            names.addDictPart(\" \", \" \");\n            names.addDictPart(\"of\", \"of\");\n            names.addDictPart(\"ember\", \"Ember,Cinder,Ash,Smoke,Soot\");\n            names.addDictPart(\"feud\", \"Feud,Quarrel,Grudge,Blaze\");\n            names.addTemplate(\"ember, ,feud\");\n            names.addTemplate(\"ember, ,feud, ,of, ,kingdom_name\");\n\n            AssetManager.name_generator.add(names);\n        }\n\n        /** Start one. The game's own wars go through this same method. */\n        public static War Start(Kingdom pAttacker, Kingdom pDefender)\n        {\n            WarTypeAsset feud = AssetManager.war_types_library.get(FEUD);\n            if (feud == null || pAttacker == null || pDefender == null) return null;\n\n            // internal: compiles inside NML. It checks there is no war between them already,\n            // logs it in the world history, and pulls in the allies when alliance_join is on.\n            return World.world.diplomacy.startWar(pAttacker, pDefender, feud);\n        }\n    }\n}",
  "kingdom_ai": "using System;\nusing ai.behaviours;\n\nnamespace HelloBox\n{\n    public class BehHelloCheckTribute : BehaviourActionKingdom\n    {\n        public override BehResult execute(Kingdom pKingdom)\n        {\n            if (pKingdom == null || pKingdom.isRekt() || !pKingdom.isCiv()) return BehResult.Stop;\n            if (pKingdom.capital == null || pKingdom.king == null) return BehResult.Stop;\n\n            // Example directive: if the kingdom has plenty of gold, donate to treasury\n            if (pKingdom.data.gold > 300)\n            {\n                pKingdom.data.gold += 10;\n                return BehResult.Continue;\n            }\n\n            return BehResult.Stop;\n        }\n    }\n\n    public static class HelloKingdomAI\n    {\n        public const string TASK_ID = \"hello_kingdom_tribute\";\n\n        public static void Initialize()\n        {\n            if (AssetManager.tasks_kingdom.has(TASK_ID)) return;\n\n            // 1. Define the task\n            BehaviourTaskKingdom task = new BehaviourTaskKingdom\n            {\n                id = TASK_ID\n            };\n\n            // 2. Add steps\n            task.addBeh(new BehHelloCheckTribute());\n\n            AssetManager.tasks_kingdom.add(task);\n\n            // 3. Inject into the civ kingdom job\n            KingdomJob civJob = AssetManager.job_kingdom.get(\"civ\");\n            if (civJob != null && !civJob.tasks.Contains(TASK_ID))\n            {\n                civJob.tasks.Add(TASK_ID);\n            }\n        }\n    }\n}",
  "build_order": "using System;\nusing System.Collections.Generic;\n\nnamespace HelloBox\n{\n    public static class HelloBuildOrders\n    {\n        public const string ORDER_ID = \"order_hello_shrine\";\n\n        public static void Initialize()\n        {\n            if (AssetManager.city_build_orders.has(ORDER_ID)) return;\n\n            // 1. Create a build order rule for the shrine\n            CityBuildOrderAsset shrineOrder = new CityBuildOrderAsset\n            {\n                id = ORDER_ID,\n                building_id = \"hello_shrine\",\n                requirements_population = 15,\n                requirements_zones = 10,\n                max = 1,\n                priority = 5\n            };\n\n            AssetManager.city_build_orders.add(shrineOrder);\n\n            // 2. Insert into the human build order list\n            CityBuildOrderAsset humanOrder = AssetManager.city_build_orders.get(\"human\");\n            if (humanOrder != null && humanOrder.list != null)\n            {\n                if (!humanOrder.list.Contains(ORDER_ID))\n                {\n                    humanOrder.list.Add(ORDER_ID);\n                }\n            }\n        }\n    }\n}",
  "phenotype": "using System;\nusing System.Collections.Generic;\n\nnamespace HelloBox\n{\n    public static class HelloPhenotypes\n    {\n        public const string PHENOTYPE_ID = \"phenotype_hello_ember\";\n\n        public static void Initialize()\n        {\n            if (AssetManager.phenotype_library.has(PHENOTYPE_ID)) return;\n\n            // 1. Create the phenotype asset\n            PhenotypeAsset ember = new PhenotypeAsset\n            {\n                id = PHENOTYPE_ID,\n                localized_key = \"phenotype_name_hello_ember\",\n                chance = 10\n            };\n\n            // 2. Set allowed skin tone and hair color ranges\n            ember.colors_skin = new List<string> { \"#FF4500\", \"#FF8C00\", \"#FFA500\" };\n            ember.colors_hair = new List<string> { \"#8B0000\", \"#B22222\", \"#FF0000\" };\n\n            AssetManager.phenotype_library.add(ember);\n        }\n\n        /** Attach this phenotype to a subspecies */\n        public static void ApplyToSubspecies(Subspecies pSubspecies)\n        {\n            if (pSubspecies == null) return;\n\n            if (pSubspecies.data != null && pSubspecies.data.phenotypes != null)\n            {\n                if (!pSubspecies.data.phenotypes.Contains(PHENOTYPE_ID))\n                {\n                    pSubspecies.data.phenotypes.Add(PHENOTYPE_ID);\n                }\n            }\n        }\n    }\n}",
  "hud": "using System;\nusing UnityEngine;\nusing UnityEngine.UI;\n\nnamespace HelloBox\n{\n    public class HelloHUD : MonoBehaviour\n    {\n        private static GameObject HudObject;\n        private static Text Label;\n        private static float NextUpdate;\n\n        public static void Initialize()\n        {\n            if (HudObject != null) return;\n            if (CanvasMain.instance == null) return;\n\n            // 1. Create a root GameObject under CanvasMain\n            HudObject = new GameObject(\"HelloBox_HUD\");\n            HudObject.transform.SetParent(CanvasMain.instance.transform, false);\n\n            RectTransform rect = HudObject.AddComponent<RectTransform>();\n            rect.anchorMin = new Vector2(0f, 1f); // top-left\n            rect.anchorMax = new Vector2(0f, 1f);\n            rect.pivot = new Vector2(0f, 1f);\n            rect.anchoredPosition = new Vector2(20f, -60f);\n            rect.sizeDelta = new Vector2(200f, 40f);\n\n            // 2. Add background panel\n            Image bg = HudObject.AddComponent<Image>();\n            bg.color = new Color(0.1f, 0.12f, 0.16f, 0.85f);\n\n            // 3. Add text label\n            GameObject textObj = new GameObject(\"Label\");\n            textObj.transform.SetParent(HudObject.transform, false);\n\n            RectTransform textRect = textObj.AddComponent<RectTransform>();\n            textRect.anchorMin = Vector2.zero;\n            textRect.anchorMax = Vector2.one;\n            textRect.sizeDelta = Vector2.zero;\n\n            Label = textObj.AddComponent<Text>();\n            Label.font = Resources.GetBuiltinResource<Font>(\"Arial.ttf\");\n            Label.fontSize = 14;\n            Label.alignment = TextAnchor.MiddleCenter;\n            Label.color = Color.white;\n            Label.text = \"HelloBox: Loading...\";\n\n            HudObject.AddComponent<HelloHUD>();\n        }\n\n        private void Update()\n        {\n            if (Time.time < NextUpdate) return;\n            NextUpdate = Time.time + 1.0f;\n\n            if (World.world == null || Label == null) return;\n\n            int units = World.world.units != null ? World.world.units.Count : 0;\n            Label.text = $\"Alive units: {units}\";\n        }\n\n        public static void Destroy()\n        {\n            if (HudObject != null)\n            {\n                Destroy(HudObject);\n                HudObject = null;\n            }\n        }\n    }\n}"
};
